using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTests.LoyaltyDiscount;

public sealed class CalculatePayableTotalAcceptanceTests
{
    [Theory]
    [InlineData(LoyaltyTier.Green, 4_999, 4_750)]     // 5% of 4999 = 249.95 -> 249
    [InlineData(LoyaltyTier.Green, 5_000, 4_700)]     // threshold joins upper band: 6%
    [InlineData(LoyaltyTier.Green, 10_000, 9_400)]
    [InlineData(LoyaltyTier.Green, 19_999, 18_400)]   // 6% of 19999 = 1199.94 -> 1199
    [InlineData(LoyaltyTier.Green, 20_000, 18_400)]   // 8%
    [InlineData(LoyaltyTier.Gold, 4_999, 4_650)]      // 7% = 349.93 -> 349
    [InlineData(LoyaltyTier.Gold, 10_000, 9_200)]     // 8%
    [InlineData(LoyaltyTier.Gold, 20_000, 18_000)]    // 10%
    [InlineData(LoyaltyTier.Platinum, 4_999, 4_550)]  // 9% = 449.91 -> 449
    [InlineData(LoyaltyTier.Platinum, 5_000, 4_500)]  // 10%
    [InlineData(LoyaltyTier.Platinum, 20_000, 18_000)] // capped at 10%, not 12%
    public void CustomersPayTheApprovedLoyaltyTotal(LoyaltyTier loyaltyTier, int subtotalCents, int expectedPayableCents)
    {
        var payable = new CalculatePayableTotal().For(subtotalCents, loyaltyTier);

        Assert.Equal(expectedPayableCents, payable);
    }
}
E
